--------------------------------------------------------
--  DDL for Procedure PROC_BIFURCATE_VALIDATE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "JS_HOMEREMIT"."PROC_BIFURCATE_VALIDATE" 
(
  P_TRANS_DETAIL_ID IN NUMBER,
  P_USER_ID IN NUMBER,
  P_STATUS OUT NUMBER, 
  P_STATUSDESCR OUT VARCHAR2 
) AS 
    -- CURSOR TO CHECK TRANS DETAIL
    CURSOR C_TRANS_DETAIL IS
    SELECT STATUS
      FROM TBL_TRANS_DETAIL
     WHERE TRANS_DETAIL_ID = P_TRANS_DETAIL_ID;

    VC_TRANS_DETAIL C_TRANS_DETAIL%ROWTYPE;
    
    -- CURSOR FOR AML/NACTA BENEFICIARY CNIC VALIDATION
    CURSOR C_VAL_CNIC(V_BEN_CNIC VARCHAR2) IS
    SELECT *
      FROM TBL_NACTA_LIST
     WHERE CNIC = V_BEN_CNIC;
    
    VC_VAL_CNIC C_VAL_CNIC%ROWTYPE;
    
    -- CURSOR FOR AML/NACTA BENEFICIARY NAME VALIDATION
    CURSOR C_VAL_BEN_NAME(V_BEN_NAME VARCHAR2) IS
    SELECT *
      FROM TBL_NACTA_LIST
     WHERE UPPER(TRIM(NAME)) = UPPER(TRIM(V_BEN_NAME));
    
    VC_VAL_BEN_NAME C_VAL_BEN_NAME%ROWTYPE;
    
    -- CURSOR FOR AML/NACTA REMITTER NAME VALIDATION
    CURSOR C_VAL_REM_NAME(V_REM_NAME VARCHAR2) IS
    SELECT *
      FROM TBL_NACTA_LIST
     WHERE UPPER(TRIM(NAME)) = UPPER(TRIM(V_REM_NAME)); 
     
    VC_VAL_REM_NAME C_VAL_REM_NAME%ROWTYPE;
    
    -- CURSOR TO CHECK AMOUNT CAPPING 
    CURSOR C_AMOUNT_CAPPING(V_REMIT_CODE VARCHAR2) IS
    SELECT NVL(AMOUNT_CAPPING,0) AMOUNT_CAPPING
      FROM TBL_REMIT_MODE
     WHERE REMIT_CODE = V_REMIT_CODE;
    
    V_AMOUNT_CAPPING NUMBER;
    V_STATUS VARCHAR2(2);
    V_STATUSDESCR VARCHAR2(200);
    
BEGIN

  OPEN C_TRANS_DETAIL;
  FETCH C_TRANS_DETAIL INTO VC_TRANS_DETAIL;
  IF C_TRANS_DETAIL%NOTFOUND THEN

    CLOSE C_TRANS_DETAIL;
    P_STATUS := 0;
    P_STATUSDESCR := 'INVALID ID';
    RETURN;
  END IF;
  CLOSE C_TRANS_DETAIL;


  IF VC_TRANS_DETAIL.STATUS NOT IN ('N1') THEN

    P_STATUS := 0;
    P_STATUSDESCR := 'RECORD ALREADY PROCESSED';
    RETURN;

  END IF;

  SAVEPOINT SP;
  -- BIFURCATION PROCESS 
  FOR I IN (SELECT *
              FROM TBL_TRANS_DETAIL
             WHERE TRANS_DETAIL_ID = P_TRANS_DETAIL_ID
               AND STATUS = 'N1' AND TRANS_AMD = 'Y')
  LOOP

    IF I.BENEFICIARY_ACCOUNT_NO IS NULL AND UPPER(I.BENEFICIARY_BANK_NAME) = 'JSBL' THEN
        -- CASH OVER COUNTER
        
        OPEN C_AMOUNT_CAPPING('OC');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'OC',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;

        CONTINUE;

    END IF;

    IF I.BENEFICIARY_ACCOUNT_NO IS NULL AND UPPER(I.BENEFICIARY_BANK_NAME) IN ('MCB','ABL') THEN
        -- CHANNEL PARTNER
        
        OPEN C_AMOUNT_CAPPING('CO');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'CO',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;

        CONTINUE;

    END IF;

    IF I.BENEFICIARY_ACCOUNT_NO IS NULL AND UPPER(I.BENEFICIARY_BANK_NAME) NOT IN ('JSBL','MCB','ABL') THEN
        -- INCOMPLETE
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'IC',
               STATUS = 'O',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;

        CONTINUE;

    END IF;

    IF I.BENEFICIARY_ACCOUNT_NO IS NOT NULL AND UPPER(I.BENEFICIARY_BANK_NAME) = 'JSBL' THEN
        -- OWN BANK TRANSFER/FT 
        
        OPEN C_AMOUNT_CAPPING('AC');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'AC',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;

        CONTINUE;

    END IF;

    IF I.BENEFICIARY_ACCOUNT_NO IS NOT NULL AND UPPER(I.BENEFICIARY_BANK_NAME) NOT IN ('JSBL') THEN
        -- IBFT
        
        OPEN C_AMOUNT_CAPPING('IB');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'IB',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;

        CONTINUE;

    END IF;

    -- IF TRANSACTION DOES NOT FALL IN ANY OF ABOVE CONDITIONS THEN
    UPDATE TBL_TRANS_DETAIL
       SET TRANS_TYPE = 'IC',
           STATUS = 'O',
           STATUS_DESCR = 'INVALID TRANSACTION',
           LASTUPDATEUSER = P_USER_ID,
           LASTUPDATEDATE = SYSDATE,
           UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
     WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;

  END LOOP;
  -- BIFURCATION PROCESS END
  
  -- VALIDATION PROCESS
  FOR I IN (SELECT *
              FROM TBL_TRANS_DETAIL
             WHERE TRANS_DETAIL_ID = P_TRANS_DETAIL_ID
               AND STATUS = 'O' AND TRANS_TYPE IS NOT NULL)
  LOOP
    
    OPEN C_VAL_CNIC(I.BENEFICIARY_CNIC);
    FETCH C_VAL_CNIC INTO VC_VAL_CNIC;
    IF C_VAL_CNIC%FOUND THEN
        
        CLOSE C_VAL_CNIC;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'VBC',
               STATUS_DESCR = 'BENEFICIARY CNIC FOUND IN '||VC_VAL_CNIC.PROCESS_NAME||' LIST',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
        CONTINUE;
        
    END IF;
    CLOSE C_VAL_CNIC;
    
    
    OPEN C_VAL_BEN_NAME(I.BENEFICIARY_NAME);
    FETCH C_VAL_BEN_NAME INTO VC_VAL_BEN_NAME;
    IF C_VAL_BEN_NAME%FOUND THEN
        
        CLOSE C_VAL_BEN_NAME;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'VBN',
               STATUS_DESCR = 'BENEFICIARY NAME FOUND IN '||VC_VAL_CNIC.PROCESS_NAME||' LIST',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
        CONTINUE;
        
    END IF;
    CLOSE C_VAL_BEN_NAME;
    
    OPEN C_VAL_REM_NAME(I.REMITTER_NAME);
    FETCH C_VAL_REM_NAME INTO VC_VAL_REM_NAME;
    IF C_VAL_REM_NAME%FOUND THEN
        
        CLOSE C_VAL_REM_NAME;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'VRN',
               STATUS_DESCR = 'REMITTER NAME FOUND IN '||VC_VAL_CNIC.PROCESS_NAME||' LIST',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
        CONTINUE;
        
    END IF;
    CLOSE C_VAL_REM_NAME;
    
    UPDATE TBL_TRANS_DETAIL
       SET STATUS = 'V',
           STATUS_DESCR = 'AML/NACTA VALIDATION SUCCESSFULL',
           LASTUPDATEUSER = P_USER_ID,
           LASTUPDATEDATE = SYSDATE,
           UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
     WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
  END LOOP;
  -- VALIDATION PROCESS END
   
   
   P_STATUS := 1;
   P_STATUSDESCR := 'BIFURCATION/VALIDATION DONE SUCCESSFULLY';


EXCEPTION

    WHEN OTHERS THEN
        ROLLBACK TO SP;
        P_STATUS := 0;
        P_STATUSDESCR := SQLCODE||'-'||SQLERRM;

END PROC_BIFURCATE_VALIDATE;

/
--------------------------------------------------------
--  DDL for Procedure PROC_CHK_DUPLICATE_TRANS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "JS_HOMEREMIT"."PROC_CHK_DUPLICATE_TRANS" 
(
  P_TRANS_HEAD_ID IN NUMBER ,
  P_USER_ID IN NUMBER ,
  P_STATUS OUT NUMBER ,
  P_STATUSDESCR OUT VARCHAR2 
) AS 

    -- CURSOR TO CHECK DUPLICATE TRANSACTION
    CURSOR C_CHK_DUPLICATE(V_FININST_BANK_ID NUMBER, V_TRANSACTION_REFERENCE VARCHAR2, V_TRANS_DETAIL_ID NUMBER) IS
    SELECT 1
      FROM TBL_TRANS_HEAD H
     INNER JOIN TBL_TRANS_DETAIL D ON H.TRANS_HEAD_ID = D.TRANS_HEAD_ID
     WHERE H.FININST_BANK_ID = V_FININST_BANK_ID
       AND D.TRANSACTION_REFERENCE = V_TRANSACTION_REFERENCE
       AND D.TRANS_DETAIL_ID NOT IN (V_TRANS_DETAIL_ID);
       
    V_CHK_DUPLICATE NUMBER;   
   
BEGIN
  
  SAVEPOINT CHK_DUP;
  
  FOR I IN (SELECT *
              FROM TBL_TRANS_HEAD H
             INNER JOIN TBL_TRANS_DETAIL D ON H.TRANS_HEAD_ID = D.TRANS_HEAD_ID
             WHERE H.TRANS_HEAD_ID = P_TRANS_HEAD_ID)
  LOOP
  
    OPEN C_CHK_DUPLICATE(I.FININST_BANK_ID, I.TRANSACTION_REFERENCE, I.TRANS_DETAIL_ID);
    FETCH C_CHK_DUPLICATE INTO V_CHK_DUPLICATE;
    
    IF C_CHK_DUPLICATE%FOUND THEN
        
        CLOSE C_CHK_DUPLICATE;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'D',
               STATUS_DESCR = 'DUPLICATE TRANSACTION',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
         CONTINUE;
         
    END IF;
    CLOSE C_CHK_DUPLICATE;
    
  END LOOP;
  
  P_STATUS := 1;
  P_STATUSDESCR := 'DUPLICATE MARKED SUCCESSFULLY';

  
EXCEPTION 
    WHEN OTHERS THEN
        ROLLBACK TO CHK_DUP;
        P_STATUS := 0;
        P_STATUSDESCR := SQLERRM;
  
END PROC_CHK_DUPLICATE_TRANS;

/
--------------------------------------------------------
--  DDL for Procedure PROC_POPULATE_MT102
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "JS_HOMEREMIT"."PROC_POPULATE_MT102" 
(
  P_BATCH_NO IN NUMBER, 
  P_USER_ID IN NUMBER,
  P_MT102_HEAD_ID OUT T_MT102_HEAD_ID,
  P_STATUS OUT NUMBER,
  P_STATUSDESCR OUT VARCHAR2,
  P_HEAD_IDS OUT VARCHAR2
) AS 

    V_BANK_NAME VARCHAR2(10);
    V_DATE VARCHAR2(12);
    V_FILE_NO VARCHAR2(20);
    V_HEAD_ID NUMBER;
    V_COUNTER NUMBER;
    V_IDX NUMBER := 1;
    V_HEAD_IDX VARCHAR2(100) ;
    
     CURSOR C_BATCH_EXISTS IS
    SELECT STATUS
      FROM TBL_MT102_TEMP
     WHERE BATCH_NO = P_BATCH_NO;

    VC_BATCH_EXISTS C_BATCH_EXISTS%ROWTYPE; 

BEGIN

    OPEN C_BATCH_EXISTS;
      FETCH C_BATCH_EXISTS INTO VC_BATCH_EXISTS;
      IF C_BATCH_EXISTS%NOTFOUND THEN

        CLOSE C_BATCH_EXISTS;
        P_STATUS := 0;
        P_STATUSDESCR := 'INVALID BATCH ID';
        RETURN;
      END IF;
    CLOSE C_BATCH_EXISTS;
    
    SELECT TO_CHAR(SYSDATE,'YYMMDDHH24MI')
         INTO V_DATE
       FROM DUAL;

    P_MT102_HEAD_ID := T_MT102_HEAD_ID();

    SAVEPOINT ABC; 

    FOR I IN (SELECT B.*, A.MT102_TEMP_ID, F.BIC_CODE, F.BENEFICIARY_BANK_ACCOUNT, H.FININST_BANK_ID
                FROM TBL_MT102_TEMP A 
               INNER JOIN TBL_TRANS_DETAIL B ON A.TRANS_DETAIL_ID = B.TRANS_DETAIL_ID  
               INNER JOIN TBL_TRANS_HEAD H ON B.TRANS_HEAD_ID = H.TRANS_HEAD_ID
               INNER JOIN TBL_FININST_BANK F ON B.BENEFICIARY_BANK_NAME = F.FININST_CODE
               WHERE A.BATCH_NO = P_BATCH_NO AND A.STATUS = 'S' AND B.TRANS_TYPE= 'IB' AND B.TRANS_BT = 'Y' AND B.STATUS = 'S'
               ORDER BY B.BENEFICIARY_BANK_NAME,  A.MT102_TEMP_ID)
    LOOP

              UPDATE TBL_MT102_TEMP  
                 SET STATUS = 'I',
                     LASTUPDATEUSER = I.CREATEUSER,
                     LASTUPDATEDATE = SYSDATE,
                     UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
               WHERE MT102_TEMP_ID = I.MT102_TEMP_ID;

              IF (V_BANK_NAME IS NULL OR V_BANK_NAME !=  I.BENEFICIARY_BANK_NAME) THEN

                    V_BANK_NAME := I.BENEFICIARY_BANK_NAME;
                    V_COUNTER := 0;

              END IF;

              IF (V_COUNTER = 0 OR V_COUNTER = 10) THEN

                          V_FILE_NO := 'P'||V_DATE; --V_BANK_NAME||V_DATE||LPAD(TBL_MT102_FILEREFNO_SEQ.NEXTVAL, 6,0);
                          V_HEAD_ID := TBL_MT102_HEAD_SEQ.NEXTVAL;
                          P_MT102_HEAD_ID.EXTEND(1);
                          P_MT102_HEAD_ID(V_IDX) := V_HEAD_ID;
                          V_IDX := V_IDX + 1;

                                              VALUES(V_HEAD_ID, V_BANK_NAME, V_FILE_NO,   I.AMOUNT, 1, I.FININST_BANK_ID,'S', 'SUBMITTED', I.CREATEUSER);

                                                          REMITTER_COUNTRY, TRANSACTION_REFERENCE, AMOUNT, BENEFICIARY_NAME, BENEFICIARY_CNIC,
                                                          BENEFICIARY_ACCOUNT_NO, BENEFICIARY_BRANCH_CODE, BENEFICIARY_OTHER_CONTACT, 
                                                          BENEFICIARY_BANK_NAME, BENEFICIARY_BRANCH_ADD1, BENEFICIARY_BRANCH_ADD2,
                                                          BENEFICIARY_ACCOUNT_TITLE, CREATEUSER,TRANS_DETAIL_ID, BIC_CODE, BENEFICIARY_BANK_ACCOUNT)                    

                          VALUES (TBL_MT102_DETAIL_SEQ.NEXTVAL, V_HEAD_ID, I.REMITTER_NAME, I.REMITTER_NUMBER, I.REMITTER_ADDRESS,
                                          I.REMITTER_COUNTRY, I.TRANSACTION_REFERENCE, I.AMOUNT, I.BENEFICIARY_NAME, I.BENEFICIARY_CNIC,
                                          I.BENEFICIARY_ACCOUNT_NO, I.BENEFICIARY_BRANCH_CODE, I.BENEFICIARY_OTHER_CONTACT,
                                          I.BENEFICIARY_BANK_NAME, I.BENEFICIARY_BRANCH_ADD1, I.BENEFICIARY_BRANCH_ADD2,
                                          I.BENEFICIARY_ACCOUNT_TITLE, I.CREATEUSER, I.TRANS_DETAIL_ID, I.BIC_CODE, I.BENEFICIARY_BANK_ACCOUNT);

                          V_COUNTER := 1;            

              ELSE 

                                                       REMITTER_COUNTRY, TRANSACTION_REFERENCE, AMOUNT, BENEFICIARY_NAME, BENEFICIARY_CNIC,
                                                       BENEFICIARY_ACCOUNT_NO, BENEFICIARY_BRANCH_CODE, BENEFICIARY_OTHER_CONTACT, 
                                                       BENEFICIARY_BANK_NAME, BENEFICIARY_BRANCH_ADD1, BENEFICIARY_BRANCH_ADD2,
                                                       BENEFICIARY_ACCOUNT_TITLE, CREATEUSER, TRANS_DETAIL_ID, BIC_CODE, BENEFICIARY_BANK_ACCOUNT)                    

                        VALUES (TBL_MT102_DETAIL_SEQ.NEXTVAL, V_HEAD_ID, I.REMITTER_NAME, I.REMITTER_NUMBER, I.REMITTER_ADDRESS,
                                I.REMITTER_COUNTRY, I.TRANSACTION_REFERENCE, I.AMOUNT, I.BENEFICIARY_NAME, I.BENEFICIARY_CNIC,
                                I.BENEFICIARY_ACCOUNT_NO, I.BENEFICIARY_BRANCH_CODE, I.BENEFICIARY_OTHER_CONTACT,
                                I.BENEFICIARY_BANK_NAME, I.BENEFICIARY_BRANCH_ADD1, I.BENEFICIARY_BRANCH_ADD2,
                                I.BENEFICIARY_ACCOUNT_TITLE, I.CREATEUSER, I.TRANS_DETAIL_ID, I.BIC_CODE, I.BENEFICIARY_BANK_ACCOUNT);

                          UPDATE TBL_MT102_HEAD 
                             SET NO_OF_TRANSACTIONS = NO_OF_TRANSACTIONS + 1,
                                 TOTAL_AMOUNT = TOTAL_AMOUNT+I.AMOUNT 
                           WHERE MT102_HEAD_ID = V_HEAD_ID;

                          V_COUNTER := V_COUNTER+1;

              END IF;

    END LOOP;

    P_STATUS := 1;
    P_STATUSDESCR := 'MT102 GENERATED SUCCESSFULLY' ;

    FOR I IN 1..P_MT102_HEAD_ID.COUNT
    LOOP
           IF V_HEAD_IDX IS NULL THEN
              V_HEAD_IDX  := P_MT102_HEAD_ID(I);
           ELSE
              V_HEAD_IDX  :=  V_HEAD_IDX||','||P_MT102_HEAD_ID(I);
           END IF ;
    END LOOP;

    P_HEAD_IDS := V_HEAD_IDX;

EXCEPTION

      WHEN OTHERS THEN
        ROLLBACK TO SAVEPOINT ABC;
        P_STATUS := 0;
        P_STATUSDESCR := SQLCODE||'-'||SQLERRM;


END PROC_POPULATE_MT102;

/
--------------------------------------------------------
--  DDL for Procedure PROC_TRANS_BIFURCATE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "JS_HOMEREMIT"."PROC_TRANS_BIFURCATE" 
(
  P_TRANS_HEAD_ID IN NUMBER,
  P_USER_ID IN NUMBER,
  P_STATUS OUT NUMBER, 
  P_STATUSDESCR OUT VARCHAR2 
) AS 
    -- CURSOR TO CHECK TRANS HEAD
    CURSOR C_TRANS_HEAD IS
    SELECT STATUS
      FROM TBL_TRANS_HEAD
     WHERE TRANS_HEAD_ID = P_TRANS_HEAD_ID;
     
    VC_TRANS_HEAD C_TRANS_HEAD%ROWTYPE; 
    
    -- CURSOR TO CHECK AMOUNT CAPPING 
    CURSOR C_AMOUNT_CAPPING(V_REMIT_CODE VARCHAR2) IS
    SELECT NVL(AMOUNT_CAPPING,0) AMOUNT_CAPPING
      FROM TBL_REMIT_MODE
     WHERE REMIT_CODE = V_REMIT_CODE;
    
    V_AMOUNT_CAPPING NUMBER;
    V_STATUS VARCHAR2(2);
    V_STATUSDESCR VARCHAR2(200);
    
BEGIN
  
  OPEN C_TRANS_HEAD;
  FETCH C_TRANS_HEAD INTO VC_TRANS_HEAD;
  IF C_TRANS_HEAD%NOTFOUND THEN
    
    CLOSE C_TRANS_HEAD;
    P_STATUS := 0;
    P_STATUSDESCR := 'INVALID FILE ID';
    RETURN;
  END IF;
  CLOSE C_TRANS_HEAD;
  
  
  IF VC_TRANS_HEAD.STATUS NOT IN ('N') THEN
  
    P_STATUS := 0;
    P_STATUSDESCR := 'FILE ALREADY PROCESSED';
    RETURN;
    
  END IF;
  
  SAVEPOINT BIFURCATE;
  
  FOR I IN (SELECT *
              FROM TBL_TRANS_DETAIL
             WHERE TRANS_HEAD_ID = P_TRANS_HEAD_ID
               AND STATUS = 'N'
             ORDER BY TRANS_DETAIL_ID)
  LOOP
  
    IF I.BENEFICIARY_ACCOUNT_NO IS NULL AND UPPER(I.BENEFICIARY_BANK_NAME) = 'JSBL' THEN
        -- CASH OVER COUNTER
        
        OPEN C_AMOUNT_CAPPING('OC');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'OC',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
        
        CONTINUE;
        
    END IF;
    
    IF I.BENEFICIARY_ACCOUNT_NO IS NULL AND UPPER(I.BENEFICIARY_BANK_NAME) IN ('MCB','ABL') THEN
        
        -- CHANNEL PARTNER
        OPEN C_AMOUNT_CAPPING('CO');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'CO',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
        
        CONTINUE;
        
    END IF;
    
    IF I.BENEFICIARY_ACCOUNT_NO IS NULL AND UPPER(I.BENEFICIARY_BANK_NAME) NOT IN ('JSBL','MCB','ABL') THEN
        -- INCOMPLETE
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'IC',
               STATUS = 'O',
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
        
        CONTINUE;
        
    END IF;
    
    IF I.BENEFICIARY_ACCOUNT_NO IS NOT NULL AND UPPER(I.BENEFICIARY_BANK_NAME) = 'JSBL' THEN
        
        -- OWN BANK TRANSFER/FT 
        OPEN C_AMOUNT_CAPPING('AC');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'AC',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
        
        CONTINUE;
        
    END IF;
    
    IF I.BENEFICIARY_ACCOUNT_NO IS NOT NULL AND UPPER(I.BENEFICIARY_BANK_NAME) NOT IN ('JSBL') THEN
        -- IBFT 
        OPEN C_AMOUNT_CAPPING('IB');
        FETCH C_AMOUNT_CAPPING INTO V_AMOUNT_CAPPING;
        CLOSE C_AMOUNT_CAPPING;
        
        IF V_AMOUNT_CAPPING < I.AMOUNT THEN
            V_STATUS := 'LE';
            V_STATUSDESCR := 'Limit Exceed';
        ELSE
            V_STATUS := 'O';
        END IF;
        
        UPDATE TBL_TRANS_DETAIL
           SET TRANS_TYPE = 'IB',
               STATUS = V_STATUS,
               STATUS_DESCR = V_STATUSDESCR,
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
        
        CONTINUE;
        
    END IF;
    
    -- IF TRANSACTION DOES NOT FALL IN ANY OF ABOVE CONDITIONS THEN
    UPDATE TBL_TRANS_DETAIL
       SET TRANS_TYPE = 'IC',
           STATUS = 'O',
           STATUS_DESCR = 'INVALID TRANSACTION',
           LASTUPDATEUSER = P_USER_ID,
           LASTUPDATEDATE = SYSDATE,
           UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
     WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
  END LOOP;
  
  UPDATE TBL_TRANS_HEAD
     SET STATUS = 'O',
         LASTUPDATEUSER = P_USER_ID,
         LASTUPDATEDATE = SYSDATE,
         UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
   WHERE TRANS_HEAD_ID = P_TRANS_HEAD_ID AND STATUS = 'N';
   
   P_STATUS := 1;
   P_STATUSDESCR := 'BIFURCATION DONE SUCCESSFULLY';

   
EXCEPTION

    WHEN OTHERS THEN
        ROLLBACK TO BIFURCATE;
        P_STATUS := 0;
        P_STATUSDESCR := SQLCODE||'-'||SQLERRM;
        
END PROC_TRANS_BIFURCATE;

/
--------------------------------------------------------
--  DDL for Procedure PROC_TRANS_VALIDATE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "JS_HOMEREMIT"."PROC_TRANS_VALIDATE" 
(
  P_TRANS_HEAD_ID IN NUMBER 
, P_USER_ID IN NUMBER 
, P_STATUS OUT NUMBER 
, P_STATUSDESCR OUT VARCHAR2 
) AS 
    -- CURSOR TO CHECK TRANS HEAD
    CURSOR C_TRANS_HEAD IS
    SELECT STATUS
      FROM TBL_TRANS_HEAD
     WHERE TRANS_HEAD_ID = P_TRANS_HEAD_ID;
     
    VC_TRANS_HEAD C_TRANS_HEAD%ROWTYPE; 
    
    -- CURSOR FOR AML/NACTA BENEFICIARY CNIC VALIDATION
    CURSOR C_VAL_CNIC(V_BEN_CNIC VARCHAR2) IS
    SELECT *
      FROM TBL_NACTA_LIST
     WHERE CNIC = V_BEN_CNIC;
    
    VC_VAL_CNIC C_VAL_CNIC%ROWTYPE;
    
    -- CURSOR FOR AML/NACTA BENEFICIARY NAME VALIDATION
    CURSOR C_VAL_BEN_NAME(V_BEN_NAME VARCHAR2) IS
    SELECT *
      FROM TBL_NACTA_LIST
     WHERE UPPER(TRIM(NAME)) = UPPER(TRIM(V_BEN_NAME));
    
    VC_VAL_BEN_NAME C_VAL_BEN_NAME%ROWTYPE;
    
    -- CURSOR FOR AML/NACTA REMITTER NAME VALIDATION
    CURSOR C_VAL_REM_NAME(V_REM_NAME VARCHAR2) IS
    SELECT *
      FROM TBL_NACTA_LIST
     WHERE UPPER(TRIM(NAME)) = UPPER(TRIM(V_REM_NAME)); 
     
    VC_VAL_REM_NAME C_VAL_REM_NAME%ROWTYPE;
    
BEGIN
  
  OPEN C_TRANS_HEAD;
  FETCH C_TRANS_HEAD INTO VC_TRANS_HEAD;
  IF C_TRANS_HEAD%NOTFOUND THEN
    
    CLOSE C_TRANS_HEAD;
    P_STATUS := 0;
    P_STATUSDESCR := 'INVALID FILE ID';
    RETURN;
  END IF;
  CLOSE C_TRANS_HEAD;
  
  IF VC_TRANS_HEAD.STATUS NOT IN ('O') THEN
  
    P_STATUS := 0;
    P_STATUSDESCR := 'FILE ALREADY PROCESSED';
    RETURN;
    
  END IF;
  
  SAVEPOINT VDT;
  
  FOR I IN (SELECT *
              FROM TBL_TRANS_DETAIL
             WHERE TRANS_HEAD_ID = P_TRANS_HEAD_ID
               AND STATUS = 'O' AND TRANS_TYPE IS NOT NULL
             ORDER BY TRANS_DETAIL_ID)
  LOOP
    
    OPEN C_VAL_CNIC(I.BENEFICIARY_CNIC);
    FETCH C_VAL_CNIC INTO VC_VAL_CNIC;
    IF C_VAL_CNIC%FOUND THEN
        
        CLOSE C_VAL_CNIC;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'VBC',
               STATUS_DESCR = 'BENEFICIARY CNIC FOUND IN '||VC_VAL_CNIC.PROCESS_NAME||' LIST',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
        CONTINUE;
        
    END IF;
    CLOSE C_VAL_CNIC;
    
    
    OPEN C_VAL_BEN_NAME(I.BENEFICIARY_NAME);
    FETCH C_VAL_BEN_NAME INTO VC_VAL_BEN_NAME;
    IF C_VAL_BEN_NAME%FOUND THEN
        
        CLOSE C_VAL_BEN_NAME;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'VBN',
               STATUS_DESCR = 'BENEFICIARY NAME FOUND IN '||VC_VAL_CNIC.PROCESS_NAME||' LIST',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
        CONTINUE;
        
    END IF;
    CLOSE C_VAL_BEN_NAME;
    
    OPEN C_VAL_REM_NAME(I.REMITTER_NAME);
    FETCH C_VAL_REM_NAME INTO VC_VAL_REM_NAME;
    IF C_VAL_REM_NAME%FOUND THEN
        
        CLOSE C_VAL_REM_NAME;
        
        UPDATE TBL_TRANS_DETAIL
           SET STATUS = 'VRN',
               STATUS_DESCR = 'REMITTER NAME FOUND IN '||VC_VAL_CNIC.PROCESS_NAME||' LIST',
               LASTUPDATEUSER = P_USER_ID,
               LASTUPDATEDATE = SYSDATE,
               UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
         WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
        CONTINUE;
        
    END IF;
    CLOSE C_VAL_REM_NAME;
    
    UPDATE TBL_TRANS_DETAIL
       SET STATUS = 'V',
           STATUS_DESCR = 'AML/NACTA VALIDATION SUCCESSFULL',
           LASTUPDATEUSER = P_USER_ID,
           LASTUPDATEDATE = SYSDATE,
           UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
     WHERE TRANS_DETAIL_ID = I.TRANS_DETAIL_ID;
         
  END LOOP;
  
   UPDATE TBL_TRANS_HEAD
     SET STATUS = 'V',
         LASTUPDATEUSER = P_USER_ID,
         LASTUPDATEDATE = SYSDATE,
         UPDATEINDEX = NVL(UPDATEINDEX,0) + 1
   WHERE TRANS_HEAD_ID = P_TRANS_HEAD_ID AND STATUS IN ('O');
   
   P_STATUS := 1;
   P_STATUSDESCR := 'VALIDATION DONE SUCCESSFULLY';
   

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO VDT;
        P_STATUS := 0;
        P_STATUSDESCR := SQLCODE||'-'||SQLERRM;
        
END PROC_TRANS_VALIDATE;

